const SettingsFeature={id:"settings",name:"Settings",icon:"settings",route:!1,render(){const e=NotificationService.isMorningBriefEnabled();return`<div class="fade-in">\n      <div class="top-header"><h1>Settings</h1></div>\n      <div class="p-md" >\n\n        <div class="card mb-md" >\n          <div class="fw-600 mb-12" >Your Details</div>\n          <div class="form-group">\n            <label>Name</label>\n            <input type="text" class="input" id="set-name" value="${Utils.escapeHtml(CONFIG.advisorName||"")}" placeholder="Your full name" onblur="SettingsFeature.setName(this.value)">\n          </div>\n          <div class="form-group">\n            <label>Weekly Earnings Target (£)</label>\n            <input type="number" class="input" inputmode="decimal" id="set-target" value="${CONFIG.weeklyTarget||600}" step="10" min="0" onblur="SettingsFeature.setTarget(this.value)">\n            <div class="hint">What you want to take home this week. Everything else derives from this.</div>\n          </div>\n          <div class="form-group mb-0" >\n            <label>Weekly Sales Target (derived)</label>\n            <input type="text" class="input op-75" id="set-sales-target" value="${Utils.formatCurrency(TaxCalculator.getRequiredWeeklySales(CONFIG.weeklyTarget)).replace(".00","")}" disabled >\n            <div class="hint">Sales needed to hit your earnings target at the current ${(100*TaxCalculator.getEffectiveCommissionRate()).toFixed(1)}% effective commission rate. Change your commission structure below to update this automatically.</div>\n          </div>\n          <div class="form-group mb-0 mt-14" >\n            <label>Minimum Hourly Value (&pound;)</label>\n            <input type="number" class="input" inputmode="decimal" id="set-min-hourly" value="${CONFIG.minHourlyRate||""}" placeholder="${TaxCalculator.getMinHourlyRate().rate.toFixed(0)} (estimated)" step="1" min="0" onblur="SettingsFeature.setMinHourlyRate(this.value)">\n            <div class="hint">What your time is worth, at minimum. Only used by "Check my floor" on a visit after a price objection — leave blank to use a rough estimate from your weekly target.</div>\n          </div>\n        </div>\n\n        <div class="card mb-md" >\n          <div class="fw-600 mb-12" >Company Branding</div>\n          <div class="form-group mb-0" >\n            <label>Company Name</label>\n            <input type="text" class="input" id="set-company-name" value="${Utils.escapeHtml(CONFIG.companyName||"")}" placeholder="e.g. Your Company Ltd" onblur="SettingsFeature.setCompanyName(this.value)">\n            <div class="hint">Shown throughout the app in place of "AdvisorOS". Leave blank to use the default AdvisorOS branding.</div>\n          </div>\n        </div>\n\n        <div class="card mb-md" >\n          <div class="fw-600 mb-xs" >Business Base</div>\n          <div class="fs-12 text-secondary mb-12" >Where you normally start and return from. Used for route distance and ETA planning.</div>\n          <div class="form-group mb-0" >\n            <label>Home / Business Address</label>\n            <textarea class="textarea" id="set-business-address" placeholder="e.g. 12 Example Street, Manchester M14 7FZ" onblur="SettingsFeature.setBusinessAddress(this.value)">${Utils.escapeHtml(CONFIG.businessAddress||"")}</textarea>\n          </div>\n        </div>\n\n        <div class="card mb-md" >\n          <div class="flex items-center justify-between" >\n            <div>\n              <div class="fw-600" >Morning Brief</div>\n              <div class="fs-12 text-secondary mt-2" >7am UK time — but only if AdvisorOS is open (or was recently) around then. Phones suspend background tabs/PWAs, so this won't reliably fire overnight; it's a bonus, not a real alarm.</div>\n            </div>\n            <button class="btn btn-sm ${e?"btn-primary":"btn-outline"}" onclick="SettingsFeature.toggleMorningBrief()">\n              ${e?"On":"Off"}\n            </button>\n          </div>\n        </div>\n\n        ${this.renderAICard()}\n\n        ${this.renderAutoMessagesCard()}\n\n        ${this.renderCommissionCard()}\n\n        <div class="card mb-md" >\n          <div class="fw-600 mb-12" >Advisor Mode</div>\n          <div class="segmented">\n            <button class="segment ${"company"===CONFIG.advisorMode?"active":""}" onclick="SettingsFeature.setMode('company')">Company</button>\n            <button class="segment ${"independent"===CONFIG.advisorMode?"active":""}" onclick="SettingsFeature.setMode('independent')">Independent</button>\n          </div>\n        </div>\n\n        <div class="form-group"><label>Trade</label>\n          <select class="select" onchange="SettingsFeature.setTrade(this.value)">\n            ${CONFIG.trades.map(e=>`<option value="${e.id}" ${CONFIG.trade===e.id?"selected":""}>${e.name}</option>`).join("")}\n          </select>\n        </div>\n\n        <div class="card mb-md" >\n          <div class="fw-600 mb-12" >Units</div>\n          <div class="flex gap-md" >\n            <div class="flex-1" ><label class="fs-12 text-secondary" >Distance</label>\n              <div class="segmented mt-xs" >\n                <button class="segment ${"miles"===CONFIG.distanceUnit?"active":""}" onclick="SettingsFeature.setDistanceUnit('miles')">mi</button>\n                <button class="segment ${"km"===CONFIG.distanceUnit?"active":""}" onclick="SettingsFeature.setDistanceUnit('km')">km</button>\n              </div>\n              ${"GB"===CONFIG.country?'<div class="fs-11 text-tertiary mt-xs" >HMRC pays mileage relief in miles</div>':""}\n            </div>\n            <div class="flex-1" ><label class="fs-12 text-secondary" >Measurement</label>\n              <div class="segmented mt-xs" >\n                <button class="segment ${"mm"===CONFIG.measurementUnit?"active":""}" onclick="SettingsFeature.setMeasurementUnit('mm')">mm</button>\n                <button class="segment ${"cm"===CONFIG.measurementUnit?"active":""}" onclick="SettingsFeature.setMeasurementUnit('cm')">cm</button>\n                <button class="segment ${"inches"===CONFIG.measurementUnit?"active":""}" onclick="SettingsFeature.setMeasurementUnit('inches')">in</button>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class="divider-text">Data</div>\n        ${this.renderStorageCard()}\n        <div class="flex flex-col gap-sm" >\n          <button class="btn btn-outline btn-sm" onclick="ExportService.exportBackup()"><span class="material-symbols-rounded">backup</span>Export Backup</button>\n          <button class="btn btn-outline btn-sm" onclick="SettingsFeature.importBackup()"><span class="material-symbols-rounded">restore</span>Import Backup</button>\n          <button class="btn btn-outline btn-sm" onclick="SettingsFeature.exportCSV()"><span class="material-symbols-rounded">download</span>Export to CSV</button>\n          <input type="file" id="import-file" accept=".json" style="display:none;" onchange="SettingsFeature.handleImport(event)">\n        </div>\n\n        <div class="flex flex-col gap-sm mt-sm" >\n          <button class="btn btn-outline btn-sm text-danger border-danger-soft"  onclick="SettingsFeature.confirmWipe()">\n            <span class="material-symbols-rounded">delete_forever</span>Start fresh — delete all data\n          </button>\n        </div>\n\n        <div class="mt-xl text-center text-tertiary fs-13" >\n          <div>${CONFIG.companyName?Utils.escapeHtml(CONFIG.companyName)+" · ":""}AdvisorOS v5.0</div>\n          <div class="mt-xs" >Your day, visits, follow-ups, and money in one place.</div>\n        </div>\n      </div>\n    </div>`},renderStorageCard(){const e=App.state.storageStatus||{},t=e.mode||"checking",s=e.localStorage&&e.database&&"memory"!==t,n=s?"database":"warning",a=s?"Storage looks persistent":"Storage needs attention",i=e.warning||`Using ${t}. Keep using the same website address so your data stays in the same app storage.`,o=e.origin&&"null"!==e.origin?e.origin:window.location.href.split("#")[0];return`\n      <div class="card" style="margin-bottom:16px;border-left:4px solid ${s?"var(--secondary)":"var(--warning)"};">\n        <div class="flex gap-10 items-start" >\n          <span class="material-symbols-rounded" style="color:${s?"var(--secondary)":"var(--warning)"};">${n}</span>\n          <div class="min-w-0" >\n            <div class="fw-700 mb-xs" >${Utils.escapeHtml(a)}</div>\n            <div class="fs-12 text-secondary lh-145" >${Utils.escapeHtml(i)}</div>\n            <div class="fs-11 text-tertiary lh-135 mt-sm ow-any" >${Utils.escapeHtml(o)}</div>\n          </div>\n        </div>\n      </div>\n    `},persist(){const e={advisorName:CONFIG.advisorName,companyName:CONFIG.companyName,businessAddress:CONFIG.businessAddress,businessLatLng:CONFIG.businessLatLng||null,weeklyTarget:CONFIG.weeklyTarget,weeklySalesTarget:CONFIG.weeklySalesTarget,minHourlyRate:CONFIG.minHourlyRate,advisorMode:CONFIG.advisorMode,trade:CONFIG.trade,country:CONFIG.country,currency:CONFIG.currency,taxSystem:CONFIG.taxSystem,dateFormat:CONFIG.dateFormat,distanceUnit:CONFIG.distanceUnit,measurementUnit:CONFIG.measurementUnit,commission:CONFIG.commission,ai:CONFIG.ai,autoMessages:CONFIG.autoMessages,onboardingComplete:!0};localStorage.setItem("advisoros_config",JSON.stringify(e));try{DB.setSetting("config",e)}catch(e){}},renderCommissionCard(){const e=CONFIG.commission||{},t=e.mode||"two_stage",s=1e3,n=TaxCalculator.estimateCommission(s),a=(n/s*100).toFixed(1);return`\n      <div class="card mb-md" >\n        <div class="fw-600 mb-xs" >Commission Rate</div>\n        <div class="fs-12 text-secondary mb-12" >How commission is calculated from a sale's value.</div>\n\n        <div class="segmented mb-12" >\n          <button class="segment ${"two_stage"===t?"active":""}" onclick="SettingsFeature.setCommissionMode('two_stage')">Sale reduction + net %</button>\n          <button class="segment ${"simple"===t?"active":""}" onclick="SettingsFeature.setCommissionMode('simple')">Simple %</button>\n        </div>\n\n        ${"two_stage"===t?`\n          <div class="form-group">\n            <label>Step 1: Reduce sale value by (%)</label>\n            <input type="number" class="input" inputmode="decimal" id="set-commission-reduction" value="${e.saleReductionRate??20}" step="0.1" min="0" max="100" onblur="SettingsFeature.setSaleReductionRate(this.value)">\n            <div class="hint">e.g. 20 means the net figure is 80% of the sale value.</div>\n          </div>\n          <div class="form-group mb-0" >\n            <label>Step 2: Commission on the net (%)</label>\n            <input type="number" class="input" inputmode="decimal" id="set-commission-net" value="${e.netCommissionRate??15.25}" step="0.01" min="0" max="100" onblur="SettingsFeature.setNetCommissionRate(this.value)">\n            <div class="hint">Applied to the net figure from Step 1.</div>\n          </div>\n        `:`\n          <div class="form-group mb-0" >\n            <label>Commission Rate (%)</label>\n            <input type="number" class="input" inputmode="decimal" id="set-commission-simple" value="${e.simpleRate??10}" step="0.1" min="0" max="100" onblur="SettingsFeature.setSimpleCommissionRate(this.value)">\n            <div class="hint">Applied directly to the full sale value.</div>\n          </div>\n        `}\n\n        <div class="inset-dark mt-12 dark-note fs-12 text-secondary" >\n          Example: on a ${Utils.formatCurrency(s)} sale, commission is ${Utils.formatCurrency(n)} (${a}% effective).\n        </div>\n      </div>\n    `},renderAutoMessagesCard(){const e=CONFIG.autoMessages||{},t=!!e.enabled;return`\n      <div class="card mb-md" >\n        <div class="flex items-center justify-between" >\n          <div>\n            <div class="fw-600" >Automated Messages</div>\n            <div class="fs-12 text-secondary mt-2" >Drafts a message the evening before and morning of each visit (and an "on my way" draft when you start driving). Every draft opens the preview sheet for your review — nothing is ever sent on its own.</div>\n          </div>\n          <button class="btn btn-sm ${t?"btn-primary":"btn-outline"}" onclick="SettingsFeature.toggleAutoMessages()">\n            ${t?"On":"Off"}\n          </button>\n        </div>\n\n        ${t?`\n          <div class="fs-12 text-tertiary mt-10 lh-150" >Drafts wait in the preview sheet until you send them, so even a time you miss while the app is closed is waiting for you the next time you open it. These fire along the same lines as the Morning Brief — best treated as a prompt, not an alarm.</div>\n\n          <div class="form-group mt-10" >\n            <label>Evening-before draft (day before the visit)</label>\n            <input type="time" class="input" id="set-msg-evening" value="${String(e.eveningHour??18).padStart(2,"0")}:00" onchange="SettingsFeature.setAutoMessageHour('eveningHour', this.value)">\n          </div>\n          <div class="form-group mb-0" >\n            <label>Morning-of draft (visit day)</label>\n            <input type="time" class="input" id="set-msg-morning" value="${String(e.morningHour??8).padStart(2,"0")}:00" onchange="SettingsFeature.setAutoMessageHour('morningHour', this.value)">\n          </div>\n        `:""}\n      </div>\n    `},toggleAutoMessages(){CONFIG.autoMessages={...CONFIG.autoMessages||{},enabled:!CONFIG.autoMessages.enabled},this.persist(),"undefined"!=typeof MessageScheduler&&MessageScheduler.reschedule(),Toast.show(CONFIG.autoMessages.enabled?"Automated Messages enabled":"Automated Messages turned off","success"),this.refreshInPlace()},setAutoMessageHour(e,t){const s=parseInt((t||"18:00").split(":")[0],10);CONFIG.autoMessages={...CONFIG.autoMessages||{},[e]:Number.isFinite(s)?s:18},this.persist(),this.refreshInPlace()},renderAICard(){const e=CONFIG.ai||{},t=AIService.lastUsage,s=t?`Last call: ${"ocr"===t.type?"OCR":"draft"} · ${(t.input_tokens||0).toLocaleString()}/${(t.output_tokens||0).toLocaleString()} tokens · ${Utils.formatCurrency(t.cost??0)}`:"No AI calls yet.";return`\n      <div class="card mb-md" >\n        <div class="flex items-center justify-between" >\n          <div>\n            <div class="fw-600" >Claude AI</div>\n            <div class="fs-12 text-secondary mt-2" >Reads scanned documents (Scan screen) and drafts customer messages (Talk screen).</div>\n          </div>\n          <button class="btn btn-sm ${e.enabled?"btn-primary":"btn-outline"}" onclick="SettingsFeature.toggleAI()">\n            ${e.enabled?"On":"Off"}\n          </button>\n        </div>\n\n        <div class="fs-12 text-tertiary mt-10 lh-150" >Works through your own serverless function (Vercel), which holds the API key — it never ships inside this app. Deploy <code class="fs-11" >api/claude.mjs</code> (Vercel) with your <code class="fs-11" >ANTHROPIC_API_KEY</code> environment variable, then paste the function URL below.</div>\n\n        <div class="form-group mt-10" >\n          <label>Proxy URL</label>\n          <input type="text" class="input" id="set-ai-url" value="${Utils.escapeHtml(e.proxyUrl||"")}" placeholder="https://your-site.vercel.app/api/claude" onblur="SettingsFeature.setAIUrl(this.value)">\n        </div>\n        <div class="form-group">\n          <label>Shared Secret (optional)</label>\n          <input type="password" class="input" id="set-ai-secret" value="" placeholder="${e.secret?"Saved — leave blank to keep it":"Only if your proxy requires X-AI-Key"}" onblur="SettingsFeature.setAISecret(this.value)">\n        </div>\n        <div class="form-group">\n          <label>OCR model (document reading)</label>\n          <select class="select" id="set-ai-ocr-model" onchange="SettingsFeature.setAIModel('ocrModel', this.value)">\n            <option value="claude-sonnet-4-5" ${"claude-sonnet-4-5"===e.ocrModel?"selected":""}>Claude Sonnet 4.5 — best accuracy</option>\n            <option value="claude-3-7-sonnet-latest" ${"claude-3-7-sonnet-latest"===e.ocrModel?"selected":""}>Claude Sonnet 3.7</option>\n            <option value="claude-haiku-4-5" ${"claude-haiku-4-5"===e.ocrModel?"selected":""}>Claude Haiku 4.5 — fastest/cheapest</option>\n          </select>\n        </div>\n        <div class="form-group mb-0" >\n          <label>Draft model (message writing)</label>\n          <select class="select" id="set-ai-draft-model" onchange="SettingsFeature.setAIModel('draftModel', this.value)">\n            <option value="claude-haiku-4-5" ${"claude-haiku-4-5"===e.draftModel?"selected":""}>Claude Haiku 4.5 — fast & cheap</option>\n            <option value="claude-sonnet-4-5" ${"claude-sonnet-4-5"===e.draftModel?"selected":""}>Claude Sonnet 4.5 — higher quality</option>\n            <option value="claude-3-5-haiku-latest" ${"claude-3-5-haiku-latest"===e.draftModel?"selected":""}>Claude Haiku 3.5</option>\n          </select>\n        </div>\n\n        <div class="inset-dark mt-12 dark-note fs-12 text-secondary" >${Utils.escapeHtml(s)}</div>\n        <button class="btn btn-outline btn-sm btn-block mt-10"  onclick="SettingsFeature.testAI()"><span class="material-symbols-rounded fs-16" >bolt</span>Test connection</button>\n      </div>\n    `},toggleAI(){CONFIG.ai={...CONFIG.ai||{},enabled:!CONFIG.ai.enabled},this.persist(),Toast.show(CONFIG.ai.enabled?"Claude AI enabled":"Claude AI turned off","success"),this.refreshInPlace()},setAIUrl(e){CONFIG.ai={...CONFIG.ai||{},proxyUrl:e.trim()},this.persist(),Toast.show("AI proxy URL saved","success")},setAISecret(e){const t=(e||"").trim();t&&(CONFIG.ai={...CONFIG.ai||{},secret:t},this.persist(),Toast.show("AI secret saved","success"))},setAIModel(e,t){CONFIG.ai={...CONFIG.ai||{},[e]:t},this.persist(),Toast.show("AI model updated","success")},async testAI(){const e=event?.currentTarget;e&&(e.disabled=!0,e.textContent="Testing…");try{const e=await AIService.testConnection();e.ok?Toast.show("Connected — "+e.model+" responded","success"):e.unavailable?Toast.show("timeout"===e.reason?"Connection timed out":"Proxy unreachable — check the URL","error"):Toast.show(e.message||"Proxy error — check the URL and env vars","error")}catch(e){Toast.show("Test failed: "+e.message,"error")}finally{e&&(e.disabled=!1,e.textContent="Test connection"),this.refreshInPlace()}},refreshInPlace(){const e=document.getElementById("main");if(!e)return;const t=e.scrollTop;e.innerHTML=this.render(),e.scrollTop=t},setCommissionMode(e){CONFIG.commission={...CONFIG.commission||{},mode:e},this.persist(),this.refreshInPlace()},setSaleReductionRate(e){const t=parseFloat(e);if(!Number.isFinite(t)||t<0||t>100)return Toast.show("Enter a percentage between 0 and 100","error"),void this.refreshInPlace();CONFIG.commission={...CONFIG.commission||{},saleReductionRate:t},this.persist(),Toast.show("Commission rate updated","success"),this.refreshInPlace()},setNetCommissionRate(e){const t=parseFloat(e);if(!Number.isFinite(t)||t<0||t>100)return Toast.show("Enter a percentage between 0 and 100","error"),void this.refreshInPlace();CONFIG.commission={...CONFIG.commission||{},netCommissionRate:t},this.persist(),Toast.show("Commission rate updated","success"),this.refreshInPlace()},setSimpleCommissionRate(e){const t=parseFloat(e);if(!Number.isFinite(t)||t<0||t>100)return Toast.show("Enter a percentage between 0 and 100","error"),void this.refreshInPlace();CONFIG.commission={...CONFIG.commission||{},simpleRate:t},this.persist(),Toast.show("Commission rate updated","success"),this.refreshInPlace()},setCompanyName(e){CONFIG.companyName=e.trim(),this.persist(),App.setBranding?.(),Toast.show("Company name updated","success")},setBusinessAddress(e){const t=e.trim();t!==(CONFIG.businessAddress||"")&&(CONFIG.businessLatLng=null),CONFIG.businessAddress=t,this.persist(),Toast.show("Business base updated","success")},setName(e){CONFIG.advisorName=e.trim(),this.persist(),Toast.show("Name updated","success")},setTarget(e){const t=parseFloat(e);!t||t<=0?Toast.show("Please enter a valid target","error"):(CONFIG.weeklyTarget=t,this.persist(),Toast.show("Weekly target updated","success"),this.refreshInPlace())},setMinHourlyRate(e){if(""===e||null==e)return CONFIG.minHourlyRate=null,this.persist(),Toast.show("Using an estimated hourly value instead","info"),void this.refreshInPlace();const t=parseFloat(e);!t||t<=0?Toast.show("Please enter a valid hourly rate","error"):(CONFIG.minHourlyRate=t,this.persist(),Toast.show("Minimum hourly value updated","success"),this.refreshInPlace())},async toggleMorningBrief(){NotificationService.isMorningBriefEnabled()?(NotificationService.disableMorningBrief(),Toast.show("Morning brief turned off","info")):await NotificationService.scheduleMorningBrief()?Toast.show("Morning brief queued for 7am when app is active","success"):Toast.show("Notification permission denied","error"),this.refreshInPlace()},async setMode(e){CONFIG.advisorMode=e,this.persist(),Toast.show(`Switched to ${e} mode`,"success"),this.refreshInPlace()},async setTrade(e){CONFIG.trade=e,this.persist()},async setDistanceUnit(e){CONFIG.distanceUnit=e,this.persist(),this.refreshInPlace()},async setMeasurementUnit(e){CONFIG.measurementUnit=e,this.persist(),this.refreshInPlace()},importBackup(){document.getElementById("import-file").click()},async handleImport(e){const t=e.target.files[0];if(t)try{await ExportService.importBackup(t),Toast.show("Data imported — reloading","success"),setTimeout(()=>location.reload(),600)}catch(e){Toast.show("Import failed: "+e.message,"error")}},exportCSV(){ExportService.exportCSV("appointments"),ExportService.exportCSV("expenses"),ExportService.exportCSV("trips")},confirmWipe(){App.openModal('\n      <div class="sheet-handle"></div>\n      <div class="sheet-header">\n        <h3>Delete everything?</h3>\n        <button class="btn btn-ghost btn-sm" onclick="App.closeModal()">\n          <span class="material-symbols-rounded">close</span>\n        </button>\n      </div>\n      <div class="sheet-body">\n        <div class="fs-14 text-secondary lh-150 mb-14" >\n          This permanently deletes every customer, visit, order, photo, expense and message — plus all your settings and targets. There is <strong>no undo</strong>, so export a backup first if you might need this data again.\n        </div>\n        <button class="btn btn-danger btn-block" onclick="SettingsFeature.confirmWipeFinal()">\n          <span class="material-symbols-rounded">warning</span> Yes — delete all my data\n        </button>\n        <button class="btn btn-outline btn-block mt-10"  onclick="App.closeModal()">Cancel</button>\n      </div>\n    ')},async confirmWipeFinal(){App.closeModal();try{await DB.deleteAllData(),Toast.show("All data deleted — starting fresh","success"),setTimeout(()=>location.reload(),600)}catch(e){console.error("Wipe failed:",e),Toast.show("Could not delete data — please try again","error")}}};App.registerFeature(SettingsFeature);
